/* 1. \u0418\u043D\u0442\u0443\u0438\u0442\u0438\u0432\u043D\u0430\u044F \u0431\u043B\u043E\u0447\u043D\u0430\u044F \u043C\u043E\u0434\u0435\u043B\u044C \u0434\u043B\u044F \u0432\u0441\u0435\u0445 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432 */
