/* 4. \u041E\u0447\u0438\u0441\u0442\u043A\u0430 \u0441\u0442\u0438\u043B\u0435\u0439 \u0441\u043F\u0438\u0441\u043A\u043E\u0432 \u0442\u043E\u043B\u044C\u043A\u043E \u0443 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432 \u0441\u043E \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u043D\u043E\u0439 \u0440\u043E\u043B\u044C\u044E list */
