/* 7. \u0420\u0430\u0431\u043E\u0442\u0430 \u0441 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F\u043C\u0438 \u0438 \u043C\u0435\u0434\u0438\u0430-\u0444\u0430\u0439\u043B\u0430\u043C\u0438 \u0431\u0435\u0437 \u043B\u0438\u0448\u043D\u0438\u0445 \u0437\u0430\u0437\u043E\u0440\u043E\u0432 */
